namespace Enterprise.Warehouse.Transactions.GUI
{
	public partial class OrderLineEntryUserControl : ZUserControl
	{
		#region Constructor

		public OrderLineEntryUserControl()
		{
			InitializeComponent();
			UpdateControls();
		}

		void UpdateControls()
		{
			CrossDockedInventoryModuleButtonGrid.InnerGrid.RemoveAction = RemoveAction.NoRemovePossible;
			CrossDockedInventoryModuleButtonGrid.InnerGrid.AllowCopyToNewRowMenuItem = false;
			HookEvents();

			CustomFieldsTabPage.RunWhenBindingOrFirstShown
			(
				delegate
				{
					var orderLine = OrderLine;
					if (orderLine != null)
					{
						customLabelsUserControl1.CustomLabelsProvider = new WhsDocketLine.CustomLabelsProvider(orderLine.Docket);
					}
				}
			);

			DetailTabPage.RunWhenBindingOrFirstShown
			(
				delegate
				{
					var orderLine = OrderLine;
					bool isCustomsOrder = orderLine != null && orderLine.IsCustomsTransaction;
					CustomsRelatedDataPanel.Visible = isCustomsOrder;
					CustomsRelatedDataNotAvailablePanel.Visible = !isCustomsOrder;
				}
			);
		}

		WhsPickableDocketLine OrderLine => (WhsPickableDocketLine)CurrentDataItem;

		#endregion

		#region Hook / Unhook Events

		void HookEvents()
		{
			CrossDockedInventoryModuleButtonGrid.Attaching += CrossDockedInventoryModuleButtonGrid_Attaching;
		}

		void UnhookEvents()
		{
			CrossDockedInventoryModuleButtonGrid.Attaching -= CrossDockedInventoryModuleButtonGrid_Attaching;
		}

		#endregion

		#region Actions

		#region CrossDockedInventoryModuleButtonGrid_Attaching

		void CrossDockedInventoryModuleButtonGrid_Attaching(object sender, ModuleButtonGridOperationCancelEventArgs args)
		{
			var orderLine = OrderLine;
			if (orderLine != null && !orderLine.IsDeleted && orderLine.PickableDocket != null)
			{
				if (orderLine.HasChanges)
				{
					args.Cancel = true;
					Globals.Message.ShowError(Res.GetString("dc74f587-3f8b-4f77-890d-d8ad9d1bda16", "Save Order Line before Attaching."));
				}
				else if (orderLine.PickableDocket.Pick != null)
				{
					args.Cancel = true;
					Globals.Message.ShowError(Res.GetString("0a08d66e-d025-470e-b447-80e382f42931", "Cannot Cross Dock a Picked Order."));
				}
				else if (orderLine.WE_CrossDockQuantity >= orderLine.WE_TransactionQuantity)
				{
					args.Cancel = true;
					Globals.Message.ShowError(Res.GetString("c3050c98-4bdf-42c6-9fa0-031ee5b22b3f", "Order Line is fully reserved."));
				}
			}
		}

		#endregion

		#endregion

		#region Dispose

		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				if (components != null)
				{
					components.Dispose();
				}

				UnhookEvents();
			}

			base.Dispose(disposing);
		}

		#endregion

		#region OnCurrentDataItemChanged

		protected override void OnCurrentDataItemChanged(EventArgs e)
		{
			base.OnCurrentDataItemChanged(e);
			if (CurrentDataItem != null)
			{
				CrossDockGroupBox.Visible = OrderLine.CanCrossDockInventory;
				DockCustomsGroupBoxAsFillWhenCrossDockGroupBoxIsNotVisible();
				SetAttributeFields();
				SetOrderLineOnCrossDockGrid();
				SetGridAndButtonsReadOnlyIfOrderIsFinalisedOrCancelled();
				ShowPerPackageQtyIfUSBonded();
			}
		}

		void DockCustomsGroupBoxAsFillWhenCrossDockGroupBoxIsNotVisible()
		{
			if (!OrderLine.CanCrossDockInventory)
			{
				CustomsRelatedDataGroupBox.Dock = DockStyle.Fill;
			}
		}

		void SetOrderLineOnCrossDockGrid()
		{
			var orderLine = OrderLine as WhsOrderLine;
			if (orderLine != null)
			{
				CrossDockedInventoryModuleButtonGrid.OrderLine = orderLine;
			}
		}

		void ShowPerPackageQtyIfUSBonded()
		{
			bool isUSBondedOrder = false;

			var orderLine = OrderLine;
			if (orderLine != null)
			{
				var order = orderLine.PickableDocket;

				isUSBondedOrder = order != null
					&& order.IsCustomsTransaction
					&& order.CountryCode == Constants.CountryCodes.UnitedStates;
			}

			CrossDockedInventoryModuleButtonGrid.InnerGrid.SetAvailability(isUSBondedOrder, new[] { "Inventory+PerPackageQty" });
		}

		void SetGridAndButtonsReadOnlyIfOrderIsFinalisedOrCancelled()
		{
			var orderLine = OrderLine;
			if (orderLine != null)
			{
				var order = orderLine.PickableDocket;
				if (order != null)
				{
					var pickFinalisedOrOrderCancelled = order.IsCancelled || order.IsPickFinalised;
					CrossDockedInventoryModuleButtonGrid.SetButtonsReadOnly(pickFinalisedOrOrderCancelled);
					CrossDockedInventoryModuleButtonGrid.InnerGrid.ReadOnly = pickFinalisedOrOrderCancelled;
				}
			}
		}

		#endregion

		#region SetAttributeFields

		void SetAttributeFields()
		{
			var line = OrderLine;
			if (line != null && line.Docket != null)
			{
				var client = line.Docket.Client;
				if (client != null)
				{
					var manager = client.PartAttributeManager;
					if (manager.IsPartAttributeUsedByOrganisation(1))
					{
						partAttrib1.GetExtension<ILabelCaptionRenderer>().Caption = manager.PartAttributeName1;
					}

					if (manager.IsPartAttributeUsedByOrganisation(2))
					{
						partAttrib2.GetExtension<ILabelCaptionRenderer>().Caption = manager.PartAttributeName2;
					}

					if (manager.IsPartAttributeUsedByOrganisation(3))
					{
						partAttrib3.GetExtension<ILabelCaptionRenderer>().Caption = manager.PartAttributeName3;
					}

					var columnManager = new PartAttributeColumnManager(CrossDockedInventoryModuleButtonGrid.InnerGrid,
						"Inventory+" + WhsInventoryViewSchema.WI_ExpiryDate.Name,
						"Inventory+" + WhsInventoryViewSchema.WI_PackingDate.Name,
						"Inventory+" + WhsInventoryViewSchema.WI_PartAttrib1.Name,
						"Inventory+" + WhsInventoryViewSchema.WI_PartAttrib2.Name,
						"Inventory+" + WhsInventoryViewSchema.WI_PartAttrib3.Name,
						"Inventory+" + WhsInventoryViewSchema.WI_SerialNumber.Name);

					columnManager.SetColumns(client);
				}
			}
		}

		#endregion
	}
